    identity:
      "澳大利亚国土面积接近整个欧洲，人口只有约2700万，绝大多数人住在东部和西南沿海的几座大城市里，广袤的内陆几乎无人。它自成一块大陆，动植物很多是别处没有的。作为南半球国家，季节和北半球相反——12月至2月是夏天，6月至8月是冬天。",
