  // ============ 丹麦 ============
  "denmark-overview": {
    identity:
      "丹麦地处北欧，面积约4.3万平方公里，人口约590万，是斯堪的纳维亚三国中面积最小、地势最为低平的国家（全境最高点仅170.86米），由日德兰半岛与500多座大小岛屿组成，以“童话王国”“设计王国”著称。",
    layout:
      "可大致分为：首都大区（哥本哈根及周边，政治经济中心）、西兰大区（罗斯基勒，历史古都区）、南丹麦大区（欧登塞所在的菲英岛与南日德兰半岛）、中日德兰大区（奥胡斯，丹麦第二大城市与湖区）、北日德兰大区（奥尔堡与斯卡恩，半岛最北端）、博恩霍尔姆（波罗的海中的独立岛屿）。",
    gettingAround:
      "哥本哈根机场是主要国际门户，铁路与高速公路网络发达，主要城市间通常2-4小时可达；国内定期航班以哥本哈根为枢纽，连接奥胡斯、奥尔堡、比隆、博恩霍尔姆四地。自驾靠右行驶，多座跨海大桥（大贝尔特桥、厄勒海峡大桥）将主要岛屿与半岛相连。属温带海洋性气候，全年温和，冬季多风少雪，夏季凉爽。餐厅账单通常已含服务费，不强制额外小费。电压230V，欧标两圆脚插头。",
    culture:
      "官方语言为丹麦语，英语普及率极高，几乎所有场合都可用英语交流。丹麦人崇尚平等与简约的生活方式，“Hygge”（惬意舒适的生活美学）是丹麦文化的核心概念之一。自行车文化发达，哥本哈根是全球自行车出行比例最高的城市之一。餐厅账单通常不强制小费，凑整即可。",
    seeAndDo:
      "自然地貌：默恩岛白垩崖、斯特文斯崖（世界遗产）、斯卡恩岬角、鲁比耶克努德沙丘、锡尔克堡湖区。历史人文：哥本哈根小美人鱼像与新港、罗斯基勒大教堂（世界遗产）与维京船博物馆、赫尔辛格克伦堡城堡（《哈姆雷特》原型地，世界遗产）。海岛：博恩霍尔姆花岗岩海岸、瓦登海（世界遗产）。",
    whenAndTips:
      "5-9月天气最宜人、日照最长，是旅游旺季；6月仲夏节前后各地有传统篝火庆典。跨海大桥与渡轮网络发达，适合安排跨岛自驾环线。",
  },
