  // ============ 芬兰 ============
  "finland-overview": {
    identity:
      "芬兰地处北欧，面积约34万平方公里，人口约560万，以“千湖之国”著称——境内湖泊超过18.8万座，森林覆盖率约73%，从南部的群岛海岸到北极圈内的拉普兰荒野跨越显著的纬度与地貌差异。",
    layout:
      "可大致分为：乌西马（赫尔辛基及周边，政治经济中心）、西南芬兰（图尔库、玛丽港，群岛与自治区）、湖区芬兰（坦佩雷、萨翁林纳、库奥皮奥，芬兰内陆湖区核心）、北芬兰含拉普兰（奥卢、罗瓦涅米、伊纳里，北极圈内荒原与图恩图里山地）。",
    gettingAround:
      "赫尔辛基万塔机场是主要国际门户，国内航线以赫尔辛基为枢纽通达全国主要城市，铁路网络覆盖南部与中部，前往拉普兰地区通常需要乘飞机或夜间火车。自驾靠右行驶。属温带大陆性气候（南部）过渡到亚北极气候（北部），北部拉普兰冬季严寒漫长、有极夜与极光，夏季有极昼。餐厅账单通常已含服务费，不强制额外小费。电压230V，欧标两圆脚插头。",
    culture:
      "官方语言为芬兰语与瑞典语（西南部与奥兰群岛通行瑞典语），英语普及率极高。芬兰人性格内敛、崇尚安静与个人空间，桑拿文化是芬兰社会生活的核心组成部分（全国桑拿房数量超过人口的三分之一）。桑拿传统上不穿泳衣、先淋浴洗净身体再入内，公共桑拿房通常按性别分开，本地人习惯垫一条小毛巾坐在长凳上。北部拉普兰地区是萨米原住民的传统聚居区。餐厅账单通常不强制小费，凑整即可。",
    seeAndDo:
      "自然地貌：塞马湖群岛与蓬卡哈尔尤蛇形丘、科利丘陵“国家风景”、萨尔帕塞尔卡终碛岭世界地质公园、克瓦尔肯群岛（世界遗产）、拉普兰荒原与哈尔蒂峰。历史人文：赫尔辛基元老院广场、图尔库城堡与大教堂、萨翁林纳奥拉维林纳城堡。极地体验：罗瓦涅米的圣诞老人村与极光观测。",
    whenAndTips:
      "6-8月是南部旅游旺季、日照最长；拉普兰地区12-次年3月可观测极光，6-7月可见极昼；跨越南北的行程建议乘国内航班衔接，火车更适合区域内深度游览。",
  },
